from __future__ import annotations

from marshmallow import EXCLUDE, Schema, ValidationError, fields, validates_schema
from marshmallow.validate import OneOf


class _SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE  # drop unknown keys

    username = fields.String(required=True)
    email = fields.Email(required=True)

    plan = fields.String(
        missing="free",
        validate=OneOf(["free", "pro", "team"], error="Must be one of: free, pro, team."),
    )

    age = fields.Integer(required=False)

    @fields.validates("username")
    def _validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates_schema
    def _validate_age(self, data, **kwargs) -> None:
        # Only validate when present (optional field).
        if "age" in data and data["age"] is not None:
            if not (16 <= int(data["age"]) <= 120):
                raise ValidationError({"age": ["Age must be between 16 and 120."]})


class SignupValidationError(ValueError):
    def __init__(self, messages: dict[str, list[str]]):
        super().__init__("invalid signup data")
        self.messages = messages


def validate_signup(data: dict) -> dict:
    """
    Validate and clean signup payload.

    Required: username (alphanumeric), email (valid email)
    Optional: plan (default 'free', one of 'free'|'pro'|'team'), age (16..120)
    Unknown keys are dropped.

    Returns cleaned dict; raises ValueError with .messages on invalid input.
    """
    schema = _SignupSchema()
    try:
        return schema.load(data)
    except ValidationError as err:
        # marshmallow gives messages as dict[str, list[str] | nested], normalize to dict[str, list[str]]
        messages = {}
        for field, field_messages in err.messages.items():
            if isinstance(field_messages, list):
                messages[field] = [str(m) for m in field_messages]
            else:
                # In case of unexpected structure, stringify.
                messages[field] = [str(field_messages)]
        raise SignupValidationError(messages) from None

