from __future__ import annotations

from marshmallow import EXCLUDE, Schema, ValidationError, fields, validates


class _SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free")
    age = fields.Integer(required=False)

    @validates("username")
    def _validate_username(self, value: str) -> None:
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")

    @validates("plan")
    def _validate_plan(self, value: str) -> None:
        allowed = {"free", "pro", "team"}
        if value not in allowed:
            raise ValidationError(f"Plan must be one of {sorted(allowed)}.")

    @validates("age")
    def _validate_age(self, value: int) -> None:
        if value < 16 or value > 120:
            raise ValidationError("Age must be between 16 and 120 inclusive.")


def validate_signup(data: dict) -> dict:
    """
    Validate and clean sign-up payload.

    Required:
      - username: alphanumeric string
      - email: valid email address
    Optional:
      - plan: defaults to "free", must be one of "free", "pro", "team"
      - age: integer between 16 and 120 inclusive
    Unknown keys are dropped.

    Returns the cleaned dict on success.
    On failure, raises ValueError with a `messages` attribute:
      {field_name: [error_messages...], ...}
    """
    try:
        return _SignupSchema().load(data)
    except ValidationError as err:
        exc = ValueError("invalid sign-up data")
        exc.messages = err.messages
        raise exc
